const pool=require("../config/db"),calculer=async(req,res)=>{const famille_id=req.params.famille_id;try{const appareils=(await pool.query("SELECT * FROM appareil WHERE famille_id = $1",[famille_id])).rows;if(0===appareils.length)return res.status(400).json({erreur:"Aucun appareil trouve pour cette famille"});let total_w_jour=0,total_wh_nuit=0;appareils.forEach((a=>{total_w_jour+=a.puissance_w,total_wh_nuit+=a.puissance_w*a.heures_nuit}));const puissance_panneau_w=100*(total_w_jour+total_wh_nuit)/40,capacite_batterie_wh=total_wh_nuit/1.5;await pool.query("INSERT INTO resultat_calcul\n        (famille_id, total_w_jour, total_wh_nuit, puissance_panneau_w, capacite_batterie_wh)\n       VALUES ($1, $2, $3, $4, $5)",[famille_id,total_w_jour,total_wh_nuit,puissance_panneau_w,capacite_batterie_wh]),res.json({total_w_jour:total_w_jour,total_wh_nuit:total_wh_nuit,puissance_panneau_w:puissance_panneau_w,capacite_batterie_wh:capacite_batterie_wh})}catch(err){res.status(500).json({erreur:err.message})}},getHistorique=async(req,res)=>{try{const result=await pool.query("SELECT * FROM resultat_calcul\n       WHERE famille_id = $1\n       ORDER BY date_calcul DESC",[req.params.famille_id]);res.json(result.rows)}catch(err){res.status(500).json({erreur:err.message})}};module.exports={calculer:calculer,getHistorique:getHistorique};